"""Add the desktop-focused evidence review to the original slide comparison."""
import html
import json
import re
from pathlib import Path

SOURCES = {
 'nielsen': ('Jakob Nielsen · 10 Usability Heuristics', 'https://www.nngroup.com/articles/ten-usability-heuristics/', 'Heuristic guidance', 'Read heuristics 1–3, 5–7 and 9. Supports familiar terminology, visible state, prevention, recovery and expert shortcuts. These are broad heuristics, not proof of a particular layout.'),
 'vv': ('Jeff Stewart · Build Great Tools, GDC 2018', 'https://media.gdcvault.com/gdc2018/presentations/Stewart_Jeff_BuildGreatTools.pdf', 'Production practice', 'Read PDF pp.25–26, 33–36 and 40–46: grouping and adjacent workflow, content models, undo, preview and recovery. Stewart explicitly cites Nielsen on p.33: this is a production application of that principle, not an independent experiment.'),
 'mk': ('Etienne Palmer-Campbell · Mission Kontrol, GDC 2025', 'https://media.gdcvault.com/gdc2025/Slides/Palmer-Campbell_Etienne_MissionKontrolRevolutionizing.pdf', 'Production case', 'Read PDF pp.45–49. QA feedback led to both-player controls and frame stepping in the tool. The case documents an iteration, not a controlled comparison or a Python implementation.'),
 'testing': ('Kate Moran · Usability Testing 101, NN/G', 'https://www.nngroup.com/articles/usability-testing-101/', 'Research-method guidance', 'Read Elements of Usability Testing, Tasks and Participants. Supports realistic tasks and observing behavior while avoiding coaching. Pair with the production case and local peer-test observations.'),
 'proximity': ('Aurora Harley · Proximity Principle in Visual Design, NN/G', 'https://www.nngroup.com/articles/gestalt-proximity/', 'Visual-design explanation', 'Read Close Proximity Indicates Relatedness and the grouped-form illustration. Supports using spacing to communicate relationships. It does not supply a measured gain for our Unreal interface.'),
 'layout': ('Microsoft · Layout, Windows desktop guidance', 'https://learn.microsoft.com/en-us/windows/win32/uxguide/vis-layout', 'Desktop platform guidance', 'Read Grouping, Alignment and sizing/resizing guidance. Use relationships and hierarchy; do not import legacy Windows styling, numeric spacing rules or group-count limits into Qt/Slate as universal requirements. The page identifies its Windows 7 origin.'),
 'keys': ('Microsoft · Keyboard accelerators', 'https://learn.microsoft.com/en-us/windows/apps/develop/input/keyboard-accelerators', 'Desktop platform guidance', 'Read When to use keyboard accelerators, Scoped accelerators and menu-label examples. Supports discoverable shortcuts for frequent actions and explicit focus scope. The API examples are Windows APIs, not PySide or Unreal code.'),
 'errors': ('Microsoft · Error Messages in Windows 7', 'https://learn.microsoft.com/en-us/windows/win32/uxguide/mess-error', 'Historical desktop guidance', 'Read Characteristics of good error messages. Supports specific, actionable explanations. Use the message structure, not its dated visual styling; retain diagnostic detail separately when needed.')
}

TOPICS = [
 ('1','Artist’s task and representation','36, 37, 40',['nielsen','vv'],'Highest priority: direct artist-tool example plus general guidance. Natoli 01–05 reinforces the framing.', 'State the intended outcome and use terms the artist can act on. Do not expose each internal function as a separate user decision.'),
 ('2','Scope, preview and recovery','39, 41–44',['nielsen','vv','errors'],'Highest priority: directly relevant to tools that modify assets. Multiple guidance sources plus production practice.', 'Show affected objects, explain whether anything changed, and provide a recovery route that the tool actually supports.'),
 ('3','Observe work and iterate','45–46, peer-test lab',['testing','mk'],'Highest priority: method guidance plus a documented game-development iteration from a separate organization.', 'Give a realistic task, observe a difficulty, make a targeted revision and retest. Do not substitute preference votes for task evidence.'),
 ('4','Grouping and visual hierarchy','38–39, new 39A',['proximity','layout','vv'],'Strong visual addition: NN/G and Microsoft agree on grouping; Stewart discusses it in a content-tool context.', 'Use spacing and alignment to distinguish target, proposed change and action. Test the arrangement with the actual task.'),
 ('5','Discoverability and expert efficiency','44, new 44A',['nielsen','keys'],'Strong desktop addition: supports both learning and repeated work; directly counters a phone-only interpretation.', 'Keep a visible route to commands while providing discoverable shortcuts for frequent actions. Check focus and scope.')
]

VISUALS = [
 {'id':'grouping','title':'Group related controls with space','slide':'39A','file':'ms-desktop-grouping.png','url':'https://learn.microsoft.com/en-us/windows/win32/uxguide/images/vis-layout-image22.png','source':'layout','credit':'Microsoft · Windows desktop Layout guidance','use':'Show the existing desktop control groups first; ask what belongs together. Follow with the course material-preview capture. These are separate examples, not a matched before/after.','rights':'Microsoft screenshot guidance: retain the original image; resize only. Historical Windows UI, not current Unreal styling.'},
 {'id':'form','title':'Same fields, different grouping','slide':'39A alternative','file':'nng-form-grouping.png','url':'https://media.nngroup.com/media/editor/2020/07/02/form-whitespacegroupings.png','source':'proximity','credit':'Aurora Harley · Nielsen Norman Group · Proximity Principle in Visual Design (2020)','use':'Use as an alternative conceptual opener if the desktop screenshot is too small. Compare grouping, then transfer to artist-tool controls. This is a schematic web form, not a measured usability result.','rights':'NN/G Articles and Videos terms permit credited educational illustrations. Preserve author, organization and original article link.'},
 {'id':'shortcuts','title':'Make the shortcut discoverable','slide':'44A','file':'ms-shortcut-menu.png','url':'https://learn.microsoft.com/en-us/windows/apps/develop/input/images/accelerators/accelerators_menuitemlabel.png','source':'keys','credit':'Microsoft · Keyboard accelerators documentation','use':'Place the full menu screenshot on the left; on the right ask students to identify the visible command and its shortcut. Do not present these keys as implemented in the course tool.','rights':'Microsoft screenshot guidance: retain original pixels; resize only.'},
 {'id':'recovery','title':'A message with a next step','slide':'43','file':'ms-rename-error.png','url':'https://learn.microsoft.com/en-us/windows/win32/uxguide/images/mess-error-image1.png','source':'errors','credit':'Microsoft · Error Messages in Windows 7','use':'Use this historical rename-error screenshot beside the existing course blocked-state capture. Ask what failed and what action the user can take. Keep annotations outside the screenshot.','rights':'Microsoft screenshot guidance: retain original pixels; resize only. Historical message example, not a visual template.'}
]

def enrich(out, by_id, actual):
    e=html.escape
    def link(key,label=None):
        s=SOURCES[key]
        return f'<a href="{e(s[1])}">{e(label or s[0])}</a>'
    def evidence(keys,reason):
        return '<aside class="evidence"><h3>Corroboration and limits</h3><p>'+e(reason)+'</p><ul>'+''.join(f'<li>{link(k)} — {e(SOURCES[k][2])}. {e(SOURCES[k][3])}</li>' for k in keys)+'</ul></aside>'
    def visual(v):
        return f'<figure><a href="assets/{v["file"]}"><img loading="lazy" src="assets/{v["file"]}" alt="{e(v["title"])}"></a><figcaption>{e(v["credit"])} · {link(v["source"],"Original page")} · <a href="{v["url"]}">Original image</a></figcaption><p><strong>Use on {v["slide"]}:</strong> {e(v["use"])}</p><details><summary>Provenance / reuse</summary><p>{e(v["rights"])}</p></details></figure>'
    path=out/'index.html'
    text=path.read_text(encoding='utf-8')
    text=text.replace('No additional external research or software compatibility verification was performed for this compilation.', 'Revision 2 adds independently consulted public sources and credited visual examples. No live software compatibility testing was performed.')
    text=text.replace('Recommendation: enrich the existing UI/UX section and add one explicit grouping example.', 'Recommendation: prioritize five corroborated desktop-tool topics, with proposed additions 39A (grouping) and 44A (discoverable shortcuts).')
    text=text.replace('41–44 state, implementation, recovery and accessibility → 45 production feedback', '41–44 state, implementation, recovery and accessibility → <a href="#keys-new">44A discoverable shortcuts</a> → 45 production feedback')
    text=text.replace('</style>', '.evidence{border-left:4px solid #23786d;background:#edf7f5;padding:15px;margin-top:20px}figure{margin:20px 0;padding:20px;background:#f5f7fa}figure img{max-height:440px;object-fit:contain}figcaption{font-size:14px}table{width:100%;border-collapse:collapse}td,th{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #ccc}td{overflow-wrap:anywhere}.tablewrap{overflow-x:auto}</style>')
    intro='<section id="priorities"><h2>Revision 2 · strongest topics for desktop artist tools</h2><p>The order below is editorial priority, not a measured evidence score or a new class schedule. Natoli is a supporting voice. Core slides are anchored in public guidance and concrete desktop/game-development examples.</p><p><strong>Evidence distinctions:</strong> a heuristic is a rule of thumb; platform guidance is a recommendation; a production case documents how one team worked. Sources repeating or citing the same principle are not independent experiments. No controlled study here validates our exact tool layout.</p><div class="tablewrap"><table><thead><tr><th>Priority / topic</th><th>Current anchors</th><th>Support and decision</th></tr></thead><tbody>'
    for rank,title,slides,keys,reason,claim in TOPICS:
        intro+=f'<tr><td>{rank}. {e(title)}</td><td>{e(slides)}</td><td>{e(reason)}<br>{e(claim)}<br>'+ ' · '.join(link(k) for k in keys)+'</td></tr>'
    intro+='</tbody></table></div><p><strong>Leave in preparation notes:</strong> thumb reach, touch-size prescriptions, mobile gestures, architecture history and unsupported numerical claims. Dense desktop interfaces can support useful work; assess whether the information helps the current decision. Do not equate minimal appearance with usability.</p><p><a href="#visuals">Visual shortlist and credits</a> · <a href="#sources">Reading guide</a> · <a href="index-v1.html">Prior review</a></p></section>'
    text=text.replace('</header>','</header>'+intro,1)
    maps={36:(['nielsen','vv'],'Core: purpose and understandable representations.'),37:(['vv','testing'],'Core: include the steps before and after the tool operation.'),38:(['layout','proximity'],'Supporting comparison: two layouts are hypotheses, not ranked by appearance.'),39:(['vv','layout'],'Core: preview scope; use grouping to make it inspectable.'),40:(['nielsen','vv'],'Core: Stewart explicitly uses Nielsen’s principle; the concrete content-tool example adds production context, not an independent experiment.'),44:(['nielsen','keys','vv'],'Core: preserve the existing recovery/accessibility coverage. Add desktop efficiency in 44A rather than replacing recovery with shortcuts.'),46:(['testing','mk'],'Core: independent method guidance and production iteration. Classroom retesting is an application, not a controlled study.')}
    for n,(keys,reason) in maps.items():
        text=re.sub(fr'(<article\b[^>]*id="slide{n}"[\s\S]*?)(</article>)',lambda m:m[1]+evidence(keys,reason)+m[2],text,count=1)
    text=re.sub(r'(<article\b[^>]*id="new"[\s\S]*?)(</article>)',lambda m:m[1]+evidence(['proximity','layout','vv'],'Strong addition: multiple guidance sources agree on grouping; do not claim measured time savings.')+visual(VISUALS[0])+m[2],text,count=1)
    # Add previously omitted high-priority current slides with exact old copy and previews.
    additions=[
      (41,'15A',['Show what completed','Keep the affected targets inspectable','Explain the next available action'],'What result would you inspect before moving on?', 'Keep title, capture and crop. Replace question and add the three short statements beside the image.', 'The message says the operation completed. Now inspect the affected targets. Does the visible result match what you intended? A useful status message tells us which operation finished and what we can do next; it does not certify every other tool or bridge.', ['nielsen','vv'], 'State is a core topic. Keep operation status separate from task success and unrelated subsystem checks.'),
      (43,'15D',['Name the problem','Identify the affected input','Offer a workable next step'],'Could a classmate continue without reading the code?', 'Keep title and course blocked-state capture. Add the three message checks and replace the question. The Microsoft screenshot is an optional comparison, not a replacement theme.', 'Read this message without assuming you know the code. What failed, which input needs attention, and what can you do now? Keep detailed diagnostics available, but give the artist an actionable explanation. Do not promise Undo unless that operation actually supports it.', ['nielsen','errors','vv'], 'Strongly corroborated and directly connected to the confusing preflight/bridge output reported during preparation.'),
      (45,'16C',['Observe the surrounding workflow','Revise the tool around the task','Test the revised operation'],'What did the team learn that the original feature list missed?', 'Keep title, GDC screenshot and credit. Add the three statements and replace the question; retain the production context.', 'Mission Kontrol initially met its planned requirements. Feedback then led to controls for both players and frame stepping inside the tool. The user was working without a gamepad, so the nearby action mattered. For your test, watch the work immediately before and after the button press.', ['mk','testing'], 'Keep this production example central. It documents an iteration, not a universal layout or a Python tool.')
    ]
    for n,key,bullets,q,edit,script,keys,reason in additions:
        s=by_id[key]
        block=f'<article data-live="yes" id="slide{n}"><p class="tag">Current slide {n} · stable anchor {key} · high priority</p><h2>{e(s["title"])}</h2><div class="columns"><div><h3>Current slide</h3><img loading="lazy" src="../UnrealFirst20261013/previews/slide-{n}.png" alt="Current slide {n}"><details><summary>Exact visible text</summary><pre>{e(actual(n))}</pre></details></div><div><h3>Proposed treatment</h3><p>{e(edit)}</p><ul>'+''.join(f'<li>{e(b)}</li>' for b in bullets)+f'</ul><p><strong>{e(q)}</strong></p></div></div><h3>Read-aloud notes</h3><blockquote>{e(script)}</blockquote>'+evidence(keys,reason)+(visual(VISUALS[3]) if n==43 else '')+'</article>'
        dest=44 if n in (41,43) else 46
        text=text.replace(f'<article data-live="yes" id="slide{dest}">',block+f'<article data-live="yes" id="slide{dest}">',1)
    new='<article data-live="yes" id="keys-new"><p class="tag">Proposed addition 44A · after current slide 44</p><h2>Visible commands, faster repetition</h2><p><strong>Current state:</strong> slide 44 covers recovery/accessibility; there is no dedicated desktop-shortcut example here. Keep that coverage intact.</p><h3>Proposed slide copy</h3><ul><li>Keep a visible command for learning</li><li>Show the shortcut beside it</li><li>Make selection and keyboard focus clear</li></ul><p><strong>Which repeated action deserves a shortcut—and what should it affect?</strong></p><h3>Read-aloud notes</h3><blockquote>An artist learning a tool needs to find the command. An artist repeating the task may prefer a shortcut. We can support both. Show the shortcut where the command is learned, and make its scope predictable. A key press should not unexpectedly act on a different panel or selection. Which repeated action in your tool would benefit, and how would you test its focus behavior?</blockquote><h3>Editing direction</h3><p>Use the menu screenshot at its natural aspect ratio, with the three points beside it. This is a platform example; it does not claim these shortcuts exist in our tools. Preserve the section color and established schedule.</p>'+evidence(['keys','nielsen'],'Strong desktop addition: platform guidance and a general efficiency heuristic converge; no speed gain is claimed.')+visual(VISUALS[2])+'</article>'
    text=text.replace('<article data-live="yes" id="slide45">',new+'<article data-live="yes" id="slide45">',1)
    # Place 39A at its proposed insertion point in the review itself.
    match=re.search(r'<article data-live="yes" id="new">[\s\S]*?</article>',text)
    if match:
        text=text.replace(match[0],'').replace('<article data-live="yes" id="slide40">',match[0]+'<article data-live="yes" id="slide40">',1)
    gallery='<section data-live="no" id="visuals"><h2>Online visuals selected for the review</h2><p>Four newly sourced images are stored locally with their original pixels and credits. Existing GDC visuals remain the main production examples. Each visual has a specific teaching job; none is a generated interface.</p>'
    gallery+=''.join(visual(v) for v in VISUALS)
    gallery+='<div class="columns"><figure><img loading="lazy" src="../ExpandedDeck20261013/assets/vv-content-model.png" alt="Vicarious Visions content model"><figcaption>Jeff Stewart · Vicarious Visions · GDC 2018 · PDF p.35. Existing course extract.</figcaption><p>Use on slide 40: compare the contiguous VFX cue with underlying spawn/kill events. '+link('vv','Original presentation')+'</p></figure><figure><img loading="lazy" src="../ExpandedDeck20261013/assets/mk-feedback.png" alt="Mission Kontrol feedback iteration"><figcaption>Etienne Palmer-Campbell · NetherRealm · GDC 2025 · PDF p.47. Existing course extract.</figcaption><p>Use on slide 45: explain the feedback-driven addition of adjacent controls. '+link('mk','Original presentation')+'</p></figure></div><p>New screenshot assets remain raster originals, not editable vector masters. Preserve their credits. Rights notes: <a href="https://www.nngroup.com/contents/terms-and-conditions/#articles-and-videos">NN/G article illustrations</a> · <a href="https://www.microsoft.com/en-us/legal/intellectualproperty/copyright/permissions">Microsoft screenshot guidance</a>. GDC extracts retain existing provenance; no new reuse license is asserted.</p></section>'
    bibliography='<section data-live="no" id="sources"><h2>Reading guide and source boundaries</h2>'
    for key,s in SOURCES.items():
        bibliography+=f'<h3>{link(key)}</h3><p><strong>{e(s[2])}.</strong> {e(s[3])}</p>'
    bibliography+='<p>Consulted 14 October 2026. Revision 1 compiled the supplied notes; revision 2 adds corroboration, desktop priorities, four sourced visual candidates, three additional current-slide treatments and proposed 44A. Original transcripts and the PowerPoint remain unchanged.</p></section>'
    text=text.replace('</main>',gallery+bibliography+'</main>')
    path.write_text(text,encoding='utf-8')
    (out/'corroborating-sources.json').write_text(json.dumps({'sources':SOURCES,'priorities':TOPICS,'visuals':VISUALS},indent=2),encoding='utf-8')
